solution.solution.cpp:
#include <cctype>
#include <cstdint>
#include <cstring>
#include <optional>
#include <sstream>
#include <string>
#include <vector>

using Pattern = std::vector<std::optional<std::uint8_t>>;

std::optional<Pattern> parsePattern(const std::string& text)
{
    Pattern pattern;
    std::istringstream in{ text };
    std::string token;
    while (in >> token)
    {
        if (token == "?" || token == "??") { pattern.push_back(std::nullopt); continue; }
        if (token.size() != 2 || !std::isxdigit(static_cast<unsigned char>(token[0])) || !std::isxdigit(static_cast<unsigned char>(token[1])))
            return std::nullopt;
        pattern.push_back(static_cast<std::uint8_t>(std::stoul(token, nullptr, 16)));
    }
    if (pattern.empty()) return std::nullopt;
    return pattern;
}

std::vector<std::size_t> findAll(const std::vector<std::uint8_t>& bytes, const Pattern& pattern)
{
    std::vector<std::size_t> hits;
    if (pattern.empty() || pattern.size() > bytes.size()) return hits;
    for (std::size_t i{ 0 }; i + pattern.size() <= bytes.size(); ++i)
    {
        bool match{ true };
        for (std::size_t k{ 0 }; k < pattern.size() && match; ++k)
            match = !pattern[k].has_value() || bytes[i + k] == *pattern[k];
        if (match) hits.push_back(i);
    }
    return hits;
}

std::optional<std::uint64_t> ripTarget(const std::vector<std::uint8_t>& bytes, std::size_t instruction, std::size_t length,
                                        std::size_t displacementAt, std::uint64_t base)
{
    if (instruction + length > bytes.size() || displacementAt + 4 > length) return std::nullopt;
    std::int32_t disp;
    std::memcpy(&disp, &bytes[instruction + displacementAt], 4);
    return base + instruction + length + static_cast<std::uint64_t>(static_cast<std::int64_t>(disp));
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
static Bytes build()
{
    return { 0xCC, 0x2B, 0xC3, 0x89, 0x47, 0x1C, 0x48, 0x8B, 0x0D, 0x6A, 0x2F, 0x01, 0x00, 0xE8, 0xF5, 0x03, 0x00, 0x00,
             0x2B, 0xC3, 0x89, 0x47, 0x20, 0xC3 };
}

TEST("parsing patterns") {
    const auto p{ parsePattern("2B C3 89 47 ?? 48 8b ?") };
    CHECK(p.has_value());
    if (!p) return;
    CHECK_EQ(p->size(), 8u);
    CHECK(!(*p)[4].has_value());
    CHECK((*p)[6] == std::optional<std::uint8_t>{ 0x8B });
    CHECK(!parsePattern("").has_value());
    CHECK(!parsePattern("2B C").has_value());
    CHECK(!parsePattern("ZZ").has_value());
    CHECK(!parsePattern("2BC3").has_value());
}
TEST("finding matches") {
    const Bytes b{ build() };
    CHECK_EQ(findAll(b, *parsePattern("2B C3 89 47 ??")), (std::vector<std::size_t>{ 1, 18 }));
    CHECK_EQ(findAll(b, *parsePattern("2B C3 89 47 1C")), (std::vector<std::size_t>{ 1 }));
    CHECK_EQ(findAll(b, *parsePattern("48 8B 0D ?? ?? ?? ?? E8 ?? ?? ?? ??")), (std::vector<std::size_t>{ 6 }));
    CHECK(findAll(b, *parsePattern("90 90")).empty());
    CHECK_EQ(findAll(Bytes{ 0xAA, 0xAA, 0xAA }, *parsePattern("AA AA")), (std::vector<std::size_t>{ 0, 1 }));
}
TEST("resolving RIP-relative targets") {
    const Bytes b{ build() };
    CHECK_EQ(ripTarget(b, 6, 7, 3, 0x140002A1A).value_or(0), 0x140002A1Aull + 13 + 0x12F6A);
    CHECK_EQ(ripTarget(b, 13, 5, 1, 0x140002A1A).value_or(0), 0x140002A1Aull + 18 + 0x3F5);
    CHECK(!ripTarget(b, 20, 7, 3, 0).has_value());
}

